questions.idealAnswer:
function debounce(func, wait) {
  let timerId = null;
  return function(...args) {
    const context = this;
    if (timerId) clearTimeout(timerId);
    timerId = setTimeout(() => {
      func.apply(context, args);
    }, wait);
  };
}

